"""v54: decode-to-decode correlations. (1) The decoder lists every value two typed terms share, same cipher or across ciphers.
(2) The decode sheet's mirrors go cross-cipher (a QB's ordinal equal to the opponent's city in reduction counts) and, for a
finished game, a "decodes that hit the final" block: which names equaled the final total, either score, the margin.
(3) A new backtest: for every name type x cipher, how often its value equals the final total / a score / the margin across
every graded game, against the chance rate measured by pairing each name with a different game's final (a permutation
baseline), with lift and z — the direct test of "do the decodes correlate with how the game ends". (4) Takeaways gets the
"decodes that called last week's finals" list and the top cross-decode correlations. Rerunnable (guarded)."""
import os, sys
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'dashboard_template.html')
s = open(P, encoding='utf-8').read()
if 'function numOutcome()' in s:
    print('already applied'); sys.exit()
UNI = {'\\u00b7': '\u00b7', '\\u2014': '\u2014', '\\u2019': '\u2019', '\\u2013': '\u2013', '\\u00d7': '\u00d7', '\\u00f7': '\u00f7', '\\u201c': '\u201c', '\\u201d': '\u201d'}
def uni(t):
    for a, b in UNI.items(): t = t.replace(a, b)
    return t
def rep(old, new, n=1):
    """the template may hold either the \\uXXXX escape or the character itself — match whichever is there"""
    global s
    if s.count(old) != n and s.count(uni(old)) == n: old, new = uni(old), uni(new)
    c = s.count(old); assert c == n, ('match count %d != %d for: %s' % (c, n, old[:100])); s = s.replace(old, new)

# ---- engine additions ----
rep("/* the decode sheet for one game: every match it carries, with the association's record */",
r"""/* cross-decode: every pair of names that share a value, same cipher or across ciphers */
function crossDecode(items){const vals=[];items.forEach((it,i)=>{const g=gemAll(it.text);CIPH.forEach(([c,cl])=>vals.push({i,it,c,cl,v:g[c]}))});const out=[];
  for(let a=0;a<vals.length;a++)for(let b=a+1;b<vals.length;b++){const x=vals[a],y=vals[b];if(x.i===y.i||x.v!==y.v||x.v<5)continue;out.push({x,y,v:x.v,same:x.c===y.c})}
  return out.sort((a,b)=>(b.same-a.same)||(b.v-a.v))}
/* the numbers a finished game produced */
const finals=r=>r[NX.as]==null||r[NX.hs]==null?[]:[{v:r[NX.as]+r[NX.hs],l:'final total',k:'ftot'},{v:r[NX.as],l:`${r[NX.away]} score`,k:'fa'},{v:r[NX.hs],l:`${r[NX.home]} score`,k:'fh'},{v:Math.abs(r[NX.hs]-r[NX.as]),l:'margin',k:'fm'},{v:Math.max(r[NX.as],r[NX.hs]),l:'winning score',k:'fw'},{v:Math.min(r[NX.as],r[NX.hs]),l:'losing score',k:'fl'},{v:+(String(Math.max(r[NX.as],r[NX.hs]))+String(Math.min(r[NX.as],r[NX.hs]))),l:'score as one number',k:'fcat'}].filter(x=>x.v>0);
/* do the decodes correlate with how the game ends? every name type x cipher vs the final numbers, against a permutation baseline */
let _NO=null;function numOutcome(){if(_NO)return _NO;const G0=NUMG().filter(r=>r[NX.as]!=null&&r[NX.hs]!=null);const T={};const F=G0.map(finals);
  G0.forEach((r,gi)=>{const ents=gameEnts(r);const fin=F[gi];const other=F[(gi*7+3)%F.length];   /* a different game's final: the chance rate for a value of this size */
    ents.forEach(e=>{const g=gemAll(e.text);CIPH.forEach(([c])=>{const v=g[c];const t=T[e.k+'|'+c]=T[e.k+'|'+c]||{k:e.k,c,n:0,hit:0,base:0,by:{},ex:[]};t.n++;
      const h=fin.find(f=>f.v===v),hb=other.find(f=>f.v===v);if(h){t.hit++;const b=t.by[h.k]=t.by[h.k]||{n:0};b.n++;if(t.ex.length<6)t.ex.push({r,e,v,f:h})}if(hb)t.base++})})});
  Object.values(T).forEach(t=>{t.p=t.n?t.hit/t.n:0;t.pb=t.n?t.base/t.n:0;t.lift=t.pb?t.p/t.pb:null;t.z=t.n&&t.pb>0?(t.p-t.pb)/Math.sqrt(t.pb*(1-t.pb)/t.n):0});return _NO={T,games:G0.length}}
/* the decode sheet for one game: every match it carries, with the association's record */""")
# cross-cipher mirrors in the sheet
rep("const mir=[];const byV={};ents.forEach(e=>{const g=gemAll(e.text);CIPH.forEach(([c])=>{(byV[c+'|'+g[c]]=byV[c+'|'+g[c]]||[]).push(e)})});Object.entries(byV).forEach(([k,L])=>{const sides=new Set(L.map(e=>e.side));if(L.length>1&&sides.size>1&&sides.has('A')&&sides.has('H'))mir.push({c:k.split('|')[0],v:+k.split('|')[1],L})});return {matches:out,mirrors:mir}}",
    "const mir=[];const byV={};ents.forEach(e=>{const g=gemAll(e.text);CIPH.forEach(([c])=>{if(g[c]<5)return;(byV[g[c]]=byV[g[c]]||[]).push({e,c})})});Object.entries(byV).forEach(([v,L])=>{const sides=new Set(L.map(x=>x.e.side));if(L.length>1&&sides.has('A')&&sides.has('H'))mir.push({v:+v,L,same:new Set(L.map(x=>x.c)).size===1})});mir.sort((a,b)=>(b.same-a.same)||(b.L.length-a.L.length));return {matches:out,mirrors:mir}}")
rep("""<div><h4 style="margin:6px 0">mirrors <span class="mini">${sh.mirrors.length}</span></h4><table><thead><tr><th>value</th><th>cipher</th><th>carried by</th></tr></thead><tbody>${sh.mirrors.slice(0,30).map(m=>`<tr><td class="num"><span class="mir">${m.v}</span></td><td class="mini">${CIPH_L[m.c]}</td><td>${m.L.map(e=>`<span class="mini dim">${e.side==='A'?ng[NX.away]:e.side==='H'?ng[NX.home]:'\\u00b7'} ${e.l}</span> <b>${esc(e.text)}</b>`).join(' \\u00b7 ')}</td></tr>`).join('')||'<tr><td colspan="3" class="dim">none</td></tr>'}</tbody></table></div></div></div>`""",
    """<div><h4 style="margin:6px 0">mirrors \\u2014 decode to decode <span class="mini">${sh.mirrors.length} \\u00b7 a value both sides carry, same cipher first, then across ciphers</span></h4><table><thead><tr><th>value</th><th>carried by</th></tr></thead><tbody>${sh.mirrors.slice(0,40).map(m=>`<tr><td class="num"><span class="mir">${m.v}</span>${m.same?'':' <span class="mini dim">cross</span>'}</td><td>${m.L.map(x=>`<span class="mini dim">${x.e.side==='A'?ng[NX.away]:x.e.side==='H'?ng[NX.home]:'\\u00b7'} ${x.e.l}</span> <b>${esc(x.e.text)}</b> <span class="mini dim">${cshort(CIPH_L[x.c])}</span>`).join(' \\u00b7 ')}</td></tr>`).join('')||'<tr><td colspan="2" class="dim">none</td></tr>'}</tbody></table></div></div>
      ${ng[NX.as]!=null?(()=>{const fin=finals(ng);const ents=gameEnts(ng);const hits=[];ents.forEach(e=>{const g=gemAll(e.text);CIPH.forEach(([c,cl])=>{fin.forEach(f=>{if(g[c]===f.v)hits.push({e,c,cl,f})})})});return `<div style="margin-top:8px"><h4 style="margin:6px 0">decodes that hit the final <span class="mini">${ng[NX.away]} ${ng[NX.as]} \\u2013 ${ng[NX.home]} ${ng[NX.hs]} \\u00b7 total ${ng[NX.as]+ng[NX.hs]} \\u00b7 margin ${Math.abs(ng[NX.hs]-ng[NX.as])}</span></h4><table><thead><tr><th>name</th><th>cipher</th><th>value</th><th>= the final's</th><th>how often this name type \\u00d7 cipher hits a final</th></tr></thead><tbody>${hits.map(h=>{const t=numOutcome().T[h.e.k+'|'+h.c];return `<tr><td><span class="mini dim">${h.e.l}</span> <b>${esc(h.e.text)}</b></td><td class="mini">${h.cl}</td><td class="num"><span class="hit">${h.f.v}</span></td><td class="mini">${h.f.l}</td><td class="mini">${t?`${(100*t.p).toFixed(1)}% vs ${(100*t.pb).toFixed(1)}% by chance \\u00b7 \\u00d7${t.lift?t.lift.toFixed(2):'\\u2014'}`:''}</td></tr>`}).join('')||'<tr><td colspan="5" class="dim">no name landed on the final</td></tr>'}</tbody></table></div>`})():''}</div>`""")
# decoder: cross-decode list
rep("""</tbody></table></div>`;
  /* 2 · the decode sheet for one game */""",
    """</tbody></table>${(()=>{const X=crossDecode(terms.map(t=>({text:t})));return X.length?`<h4 style="margin:10px 0 4px">correlations between the decodes <span class="mini">${X.length} \\u00b7 two terms sharing a value, same cipher first</span></h4><div class="lt" style="gap:4px">${X.slice(0,60).map(p=>`<span style="flex-direction:row;gap:6px;padding:3px 8px"><b>${esc(p.x.it.text)}</b> <i>${cshort(p.x.cl)}</i> = <span class="mir">${p.v}</span> = <b>${esc(p.y.it.text)}</b> <i>${cshort(p.y.cl)}</i></span>`).join('')}</div>`:terms.length>1?'<p class="note">these terms share no value in any cipher</p>':''})()}</div>`;
  /* 2 · the decode sheet for one game */""")
# outcome backtest panel on the Numerology tab
rep("""  el.innerHTML=dec+sheet+walk+lead+scor+tdt;""",
    """  /* 7 · do the decodes correlate with the final? */
  const O=numOutcome();const orows=Object.values(O.T).filter(t=>t.n>=100).sort((a,b)=>b.z-a.z);const oexp2=(orows.length*0.0228).toFixed(1);const ogot2=orows.filter(t=>t.z>=2).length;
  const outc=`<div class="panel"><h3>do the decodes correlate with the final? \\u2014 ${O.games} games <span>for every name type \\u00d7 cipher: how often the name's value equalled the final total, either score, the margin, the winning or losing score, or the score written as one number \\u00b7 chance = the same name against a different game's final (a permutation baseline) \\u00b7 lift = hit \\u00f7 chance \\u00b7 ${orows.length} pairs with 100+ names; chance alone puts about ${oexp2} past z 2 \\u2014 this set has ${ogot2}</span></h3><div class="scroll" style="max-height:480px;overflow:auto"><table><thead><tr><th>name type</th><th>cipher</th><th>names</th><th>hit a final</th><th>hit %</th><th>chance %</th><th>lift</th><th>z</th><th>what it hit</th><th>examples</th></tr></thead><tbody>${orows.map(t=>`<tr><td>${ENT_L[t.k]||t.k}</td><td class="mini">${CIPH_L[t.c]}</td><td class="num">${t.n}</td><td class="num">${t.hit}</td><td class="num"><b>${(100*t.p).toFixed(1)}%</b></td><td class="num dim">${(100*t.pb).toFixed(1)}%</td><td class="num"><b style="color:${t.lift!=null&&t.z>=2?'var(--green)':t.lift!=null&&t.z<=-2?'var(--red)':'var(--txt)'}">${t.lift!=null?'\\u00d7'+t.lift.toFixed(2):'\\u2014'}</b></td><td class="num" data-v="${t.z}">${t.z>0?'+':''}${t.z.toFixed(2)}</td><td class="mini">${Object.entries(t.by).sort((a,b)=>b[1].n-a[1].n).map(([k,b])=>`${({ftot:'total',fa:'away score',fh:'home score',fm:'margin',fw:'winning score',fl:'losing score',fcat:'score as one number'})[k]} ${b.n}`).join(' \\u00b7 ')}</td><td class="mini">${t.ex.slice(0,3).map(x=>`${esc(x.e.text)} ${x.v} = ${x.f.l} (${x.r[NX.season]} wk ${x.r[NX.week]} ${x.r[NX.away]}@${x.r[NX.home]})`).join(' \\u00b7 ')}</td></tr>`).join('')}</tbody></table></div></div>`;
  el.innerHTML=dec+sheet+walk+lead+outc+scor+tdt;""")
# takeaways: last week's finals + the correlations that exist
rep("""  el.innerHTML=kp+verdict+calls+playsHtml+held_+review+players;sortableAll(el)}""",
    """  /* 7 · decodes that called last week's finals, and the decode-to-final correlations that exist at all */
  const O=numOutcome();const fin=NG.filter(r=>r[NX.season]===S&&r[NX.week]===lastWk&&r[NX.as]!=null);const fh=[];fin.forEach(r=>{const F=finals(r);gameEnts(r).forEach(e=>{const g=gemAll(e.text);CIPH.forEach(([c,cl])=>{F.forEach(f=>{if(g[c]===f.v&&f.k!=='fcat')fh.push({r,e,c,cl,f})})})})});
  const strongO=Object.values(O.T).filter(t=>t.n>=100&&t.z>=2).sort((a,b)=>b.z-a.z);const weakO=Object.values(O.T).filter(t=>t.n>=100).sort((a,b)=>b.z-a.z);
  const finHtml=`<div class="panel"><h3>decodes that called week ${lastWk}'s finals <span>${fh.length} names landed on a final total, score or margin \\u00b7 across ${fin.length} games \\u00b7 and here is the catch: at the chance rate the engine measures, roughly ${(fin.length*(weakO.length?weakO.reduce((a,t)=>a+t.pb,0)/weakO.length:0)*22*8).toFixed(0)} of these were going to land anyway</span></h3><div class="scroll" style="max-height:360px;overflow:auto"><table><thead><tr><th>game</th><th>final</th><th>name</th><th>cipher</th><th>value</th><th>= the</th><th>this name type \\u00d7 cipher hits finals</th></tr></thead><tbody>${fh.sort((a,b)=>(b.f.k==='ftot')-(a.f.k==='ftot')).map(h=>{const t=O.T[h.e.k+'|'+h.c];return `<tr><td>${tcell(h.r[NX.away])} <span class="dim">@</span> ${tcell(h.r[NX.home])}</td><td class="mono">${h.r[NX.as]}-${h.r[NX.hs]}</td><td><span class="mini dim">${h.e.l}</span> <b>${esc(h.e.text)}</b></td><td class="mini">${cshort(h.cl)}</td><td class="num"><span class="hit">${h.f.v}</span></td><td class="mini">${h.f.l}</td><td class="mini">${t?`${(100*t.p).toFixed(1)}% vs ${(100*t.pb).toFixed(1)}% chance \\u00b7 \\u00d7${t.lift?t.lift.toFixed(2):'\\u2014'}`:''}</td></tr>`}).join('')||'<tr><td colspan="7" class="dim">none</td></tr>'}</tbody></table></div></div>
    <div class="panel"><h3>decode-to-final correlations that exist at all <span>name type \\u00d7 cipher pairs whose values hit the final more often than chance by two standard deviations or more, across ${O.games} games \\u00b7 ${strongO.length} of ${weakO.length} \\u00b7 chance alone would produce about ${(weakO.length*0.0228).toFixed(1)}</span></h3>${strongO.length?`<table><thead><tr><th>name type</th><th>cipher</th><th>names</th><th>hit %</th><th>chance %</th><th>lift</th><th>z</th><th>examples</th></tr></thead><tbody>${strongO.map(t=>`<tr><td>${ENT_L[t.k]}</td><td class="mini">${CIPH_L[t.c]}</td><td class="num">${t.n}</td><td class="num"><b>${(100*t.p).toFixed(1)}%</b></td><td class="num dim">${(100*t.pb).toFixed(1)}%</td><td class="num"><b style="color:var(--green)">\\u00d7${t.lift.toFixed(2)}</b></td><td class="num">+${t.z.toFixed(2)}</td><td class="mini">${t.ex.slice(0,3).map(x=>`${esc(x.e.text)} ${x.v} = ${x.f.l} (${x.r[NX.away]}@${x.r[NX.home]} ${x.r[NX.season]} wk ${x.r[NX.week]})`).join(' \\u00b7 ')}</td></tr>`).join('')}</tbody></table>`:`<p class="note">none. No name type in any cipher lands on the final total, a score or the margin more often than pairing it with a random other game's final does \\u2014 the ${weakO.length} pairs range from \\u00d7${weakO.length?Math.min(...weakO.map(t=>t.lift||9)).toFixed(2):'\\u2014'} to \\u00d7${weakO.length?Math.max(...weakO.map(t=>t.lift||0)).toFixed(2):'\\u2014'} the chance rate and none clears z 2. The matches you see on any single game are the ones chance produces.</p>`}</div>`;
  el.innerHTML=kp+verdict+calls+playsHtml+held_+review+finHtml+players;sortableAll(el)}""")
s = s.replace("Object.assign(NOTES,{v53:", "Object.assign(NOTES,{v54:['v54','Numerology: decode-to-decode correlations in the decoder, cross-cipher mirrors, \\u201cdecodes that hit the final\\u201d per game, and the direct test of whether any name type \\u00d7 cipher lands on finals more than a permutation baseline; Takeaways lists last week\\u2019s finals that decodes called and the correlations that exist at all'],v53:", 1)
open(P, 'w', encoding='utf-8').write(s)
print('applied')
